						rtnVal += 'Content-ID: <' + cid + '>\r\n';
						rtnVal += 'Content-Transfer-Encoding: base64' + '\r\n\r\n';
						if (ctype != "") {
							rtnVal += base64.replace(/.{76}(?=.)/g,'$&\n') + '\r\n';
						} else {
							rtnVal += base64 + '\r\n';
						}
						return rtnVal;
