					$("<div class='dwp-btn'><span>" + (_opt.viewtype == "icon" ? $fn.getCodeMsg("comm.title.js033") : $fn.getCodeMsg("comm.title.js034")) + "</span></div>").appendTo($("._attach_act", _$wrap))
