		,gnb : function(opt) {
			var _me = this;
			/*
			var _gnblist = [
						    { title:"Global Hankook"
								, children : [{title:"경영진메시지",gid:"M0002"}, {title:"Strategy",gid:"M0003"}, {title:"결재게시/공지사항",gid:"M3099"}]}
							,{ title:"Playwork"
								, children : [{title:"전자메일",gid:"M1000"}, {title:"전자결재",gid:"M0010"}
									, {title:"통합일정",gid:"M0007"}, {title:"설문조사",gid:"M0008"}, {title:"회의실예약",gid:"M0018"}]}
							,{ title:"Life Story"
								, children : [{title:"자유게시판",gid:"M3004"}, {title:"VPR",gid:"VPRJ"}]}
							,{ title:"관리"
								, children : [{title:"메뉴관리",gid:"M9999"}]}
						];
			*/
			var _gnblist = [];						
			var _$ul = $("<ul></ul>").prependTo($("div.dwp-gnb-menu div.inner"));
			
			function _jsonGetParmData() {
				var _url = $dwp.core.getPath("menu") + "/api/data/collections/name/wvgnb_n?count=999";
				//console.log("_url", _url);
				return {
						url : _url
						,dataType : "json"
						,async : false
						,cache : false						
				};
			}
			
			$dwp.core.util.xAjax(_jsonGetParmData())
			.done(function(jdata){
				$(jdata).each(function(i, data){
					var _row = {};
					_row.key = data._mid;
					_row.title = $fn.getCurLangMsg(data._title);
					_row.pkey = data._pid;
					_row.unid = data["@unid"];
					_row.gid = _row.key;
					_row.subportal = data._subportal;
					_row.linktype = data._linktype;
					_row.link = data._link;
					_row.top = data._top;
					
					if (data.hasOwnProperty("_authcom") && data._authcom != ""){
						//회사코드정보 변경 - 2019-04-04 By LHJ
						//if(data._authcom.indexOf($fn.getCurUser().pinfo.comcode) == -1){return true;}
						if(data._authcom.indexOf($fn.getComCode()) == -1){return true;}						
					}
					
					if (_row.pkey == "") {
						_gnblist.push(_row);
					} else {
						$dwp.ui.tree.addchild(_row.pkey, _gnblist, _row);
					}					
				});
				var _width = 100/_gnblist.length + "%";
				$.each(_gnblist, function(i, o){
					var _$li = $("<li style='width:" + _width + "'></li>").appendTo(_$ul)
					,_$title = $("<a>" + $dwp.core.lang.getCurMsg(o.title) + "</a>").appendTo(_$li);
					
					if (o.hasOwnProperty("link") && o.link != "") {
						_$title.off("click").on("click", function(){
							if (o.subportal == "1") {
								_me._convertDisp('S');
								_me.subPortalInit(o);
							} else {
								if(o.linktype == "PAGE") {
									_me._convertDisp('M');
								}
								_me.subInit({gid : o.gid});
							}
						});
					}
					if (o.hasOwnProperty("children")) {
						_me._subgnb(_$li, o.children);
					}
				});
			})
			.fail(function(){});			
		}
		,_subgnb : function(_$li, data) {
			var _me = this, _$ul = $("<ul></ul>").appendTo(_$li);
			
			$.each(data, function(i, o){
				var _$li = $("<li></li>").appendTo(_$ul)
				,_$title = $("<a>" + $dwp.core.lang.getCurMsg(o.title) + "</a>").appendTo(_$li);
				
				_$title.off("click").on("click", function(){
					console.log(o);
					if (o.subportal == "1") {
						_me._convertDisp('S');
						_me.subPortalInit(o);
					} else {
						if(o.linktype == "PAGE") {
							_me._convertDisp('M');
						}
						_me.subInit({gid : o.gid});
					}
				});
			});
		}
		/**
		 * 서브포탈이동
		 */
		,goSubPortal : function(opt) {
			var _me = this
			,_opt = $.extend({gid:""}, opt)
			,_rtn = false;
						
			$dwp.core.util.xAjax({
				url : $dwp.core.getPath("menu") + "/api/data/collections/name/wvlink"
				,dataType : "json"
				,async : true
				,cache : false
				,data : {category : _opt.gid}
			}).done(function(jdata){
				$(jdata).each(function(i, data){
					if (data._issubportal == "1") {
						data.gid = data._mid;
						data.linktype = data._linktype;
						data.link = data._link;
						_me._convertDisp('S');
						_me.subPortalInit(data);						
					} else {
						if ( typeof _opt.callback == "function" ){
							_opt.callback();
						}
					}
				});
			});			
		}
		/**
		 * 메뉴이동함수
		 * @param	{obj}	opt
		 */
		,goMenu : function(opt) {
			var _me = this
			,_opt = $.extend({gid:""}, opt);
			
			function _go() {
				_me._convertDisp('M');
				//_me.subInit({gid : _opt.gid});
				_me.subInit(_opt);
			}
			if (_opt.gid.charAt() == "M" || _opt.gid.charAt() == "L") {
				if ( _opt.gid.charAt() == "M" ) {
					_opt.callback = function() {_go();}
					_me.goSubPortal(_opt);
				} else {
					_go();
				}
			}
		}
