						var _img_html =  "<div class='util-wrap'> <img src='" + _img_url + "' title='"+_menu.htitle +"'   class='dwp-cursor'></div>" ;
						_$div.html(_img_html);
						_$div.off("click").on("click" , function(){ _me._act(_menu)});
